it('T107 T112 real group-admin flow reads the trusted API, pauses and revokes once, persists versions and suppresses a prepared reply',async()=>{
 const w=await contractWorld();await w.approve();await w.save();await w.f.runtime.advance(w.f.ctx,w.f.runId);expect(w.f.requests).toHaveLength(2);const before=(await root.query('SELECT to_jsonb(q) value FROM quota_ledger q WHERE run_id=$1 ORDER BY id',[w.f.runId])).rows;
 const api=await createServer({config:config(),db:appDb,sessionSecret:secret('SESSION_SECRET')!,groupContracts:w.service});let posts=0;
 try{
  const flow=new GroupContractAdminFlow(async(path,body,key)=>{if(body!==undefined)posts++;const response=await api.app.inject({url:'/api/v1'+path,method:body===undefined?'GET':'POST',headers:{cookie:'oa_session='+w.session.cookie,...(body===undefined?{}:{origin:config().APP_ORIGIN,'x-csrf-token':w.session.csrf,'idempotency-key':key!})},...(body===undefined?{}:{payload:body as object})});if(response.statusCode!==200)throw new GroupContractAdminFailure(response.statusCode);return response.json().data;});
  expect((await flow.read(w.profile.document.id))?.ok).toBe(true);expect(flow.snapshot?.contract?.version).toBe(1);expect(flow.prepare('PAUSED').ok).toBe(true);const results=await Promise.all(Array.from({length:20},()=>flow.confirm()));expect(results.filter(r=>r?.ok)).toHaveLength(1);expect(posts).toBe(1);expect(flow.receipt).toMatchObject({version:2,state:'PAUSED',currentVersion:2,currentState:'PAUSED'});
  const delivery=(await db.scope(w.f.ctx,c=>c.query("SELECT id FROM deliveries WHERE source_run_id=$1 AND state='PENDING'",[w.f.runId]))).rows[0];let sent=0;expect(await sender(w.f,()=>sent++).process(w.f.ctx,delivery.id,new AbortController().signal)).toBe('SUPPRESSED');expect(sent).toBe(0);expect((await root.query('SELECT to_jsonb(q) value FROM quota_ledger q WHERE run_id=$1 ORDER BY id',[w.f.runId])).rows).toEqual(before);
  expect((await flow.read(w.profile.document.id))?.ok).toBe(true);expect(flow.canChange('PAUSED')).toBe(false);expect(flow.prepare('REVOKED').ok).toBe(true);expect((await flow.confirm())?.ok).toBe(true);expect(posts).toBe(2);expect(await flow.confirm()).toBeNull();expect((await w.service.get(w.principal,w.profile.document.id)).contract?.document).toMatchObject({version:3,state:'REVOKED'});expect(w.f.requests).toHaveLength(2);
 }finally{await api.app.close();}
});
it('T107 real group-admin API rejects stale confirmation, missing CSRF and a different authenticated actor without persistence',async()=>{
 const w=await contractWorld();await w.approve();await w.save();const api=await createServer({config:config(),db:appDb,sessionSecret:secret('SESSION_SECRET')!,groupContracts:w.service});
 try{
  const transport=(cookie:string,csrf?:string)=>async(path:string,body?:unknown,key?:string)=>{const response=await api.app.inject({url:'/api/v1'+path,method:body===undefined?'GET':'POST',headers:{cookie:'oa_session='+cookie,...(body===undefined?{}:{origin:config().APP_ORIGIN,...(csrf?{'x-csrf-token':csrf}:{}),'idempotency-key':key!})},...(body===undefined?{}:{payload:body as object})});if(response.statusCode!==200)throw new GroupContractAdminFailure(response.statusCode);return response.json().data;};
  const stale=new GroupContractAdminFlow(transport(w.session.cookie,w.session.csrf));expect((await stale.read(w.profile.document.id))?.ok).toBe(true);stale.prepare('PAUSED');await w.service.transition(w.principal,w.document.id,{delegationId:w.profile.document.id,expectedVersion:1,state:'PAUSED'},randomUUID());expect((await stale.confirm())?.ok).toBe(false);expect(stale.receipt).toBeNull();expect(await stale.confirm()).toBeNull();
  const csrf=new GroupContractAdminFlow(transport(w.session.cookie));expect((await csrf.read(w.profile.document.id))?.ok).toBe(true);csrf.prepare('REVOKED');expect((await csrf.confirm())?.ok).toBe(false);expect(csrf.snapshot).toBeNull();
  const outsiderSession=await api.sessions.create(w.f.ctx),outsider=new GroupContractAdminFlow(transport(outsiderSession.cookie,outsiderSession.csrf));expect((await outsider.read(w.profile.document.id))?.ok).toBe(false);expect(outsider.snapshot).toBeNull();expect((await w.service.get(w.principal,w.profile.document.id)).contract?.document).toMatchObject({version:2,state:'PAUSED'});expect((await root.query('SELECT version FROM group_contract_revisions WHERE contract_id=$1 ORDER BY version',[w.document.id])).rows.map(r=>Number(r.version))).toEqual([1,2]);
 }finally{await api.app.close();}
});
