it('group contract API rechecks real sessions, delegates, CSRF and ciphertext isolation without treating caller roles as authority',async()=>{
 const w=await contractWorld();await w.approve();const api=await createServer({config:config(),db:appDb,sessionSecret:secret('SESSION_SECRET')!,groupContracts:w.service});
 try{
  const body={delegationId:w.profile.document.id,expectedVersion:0,document:w.document},headers={cookie:'oa_session='+w.session.cookie,origin:config().APP_ORIGIN,'x-csrf-token':w.session.csrf,'idempotency-key':randomUUID()};
  expect((await api.app.inject({method:'POST',url:'/api/v1/group-contracts',headers:{cookie:headers.cookie},payload:body})).statusCode).toBe(403);
  const first=await api.app.inject({method:'POST',url:'/api/v1/group-contracts',headers,payload:body});expect(first.statusCode,first.payload).toBe(200);expect(first.json().data).toMatchObject({version:1,state:'ACTIVE',platformPermissionsVerified:false});
  const same=await api.app.inject({method:'POST',url:'/api/v1/group-contracts',headers,payload:body});expect(same.json().data).toMatchObject({revisionId:first.json().data.revisionId,replayed:true});
  const outsider=await api.sessions.create(w.f.ctx);const denied=await api.app.inject({url:'/api/v1/group-contracts?delegationId='+w.profile.document.id,headers:{cookie:'oa_session='+outsider.cookie}});expect(denied.statusCode).toBe(403);expect(denied.payload).not.toContain('Answer explicit group mentions');
  await expect(appDb.scope(w.admin,c=>c.query('SELECT document_ref FROM group_contract_revisions'))).rejects.toMatchObject({code:'42501'});
  for(const database of [appDb,db])await expect(database.scope(w.admin,c=>c.query('UPDATE group_contracts SET version=version+1'))).rejects.toMatchObject({code:'42501'});
  await root.query('UPDATE role_bindings SET revoked_at=clock_timestamp() WHERE tenant_id=$1 AND id=$2',[w.admin.tenantId,w.profile.document.roleBindingId]);
  expect((await api.app.inject({url:'/api/v1/group-contracts?delegationId='+w.profile.document.id,headers:{cookie:headers.cookie}})).statusCode).toBe(401);
 }finally{await api.app.close();}
});
