it('the live authority signal aborts a grouped operation after contract pause without another model or DWS call',async()=>{
 const w=await contractWorld();await w.approve();await w.save();const observer=await watchTrial(db,w.f.ctx,w.f.runId);expect(observer.signal.aborted).toBe(false);let timeout:ReturnType<typeof setTimeout>|undefined;
 try{
  const stopped=new Promise<void>((resolve,reject)=>{if(observer.signal.aborted)return resolve();observer.signal.addEventListener('abort',()=>resolve(),{once:true});timeout=setTimeout(()=>reject(Error('GROUP_CONTRACT_STOP_SIGNAL_MISSING')),2000);});
  await w.service.transition(w.principal,w.document.id,{delegationId:w.profile.document.id,expectedVersion:1,state:'PAUSED'},randomUUID());
  await stopped;expect(observer.signal.aborted).toBe(true);expect(w.f.requests).toHaveLength(0);
 }finally{if(timeout)clearTimeout(timeout);await observer.stop();}
});
