it('real pg-boss group verification consumes only the dedicated lane and does not starve a two-connection business pool',async()=>{
 const smallDb=new Database(secret('RUNTIME_DATABASE_URL')!,2),queue=new RunQueue(secret('QUEUE_DATABASE_URL')!,'synthetic-group-'+randomUUID());try{const f=await fresh(smallDb),p=await pending(f);await queue.start();expect(await queue.publish(smallDb,f.ctx)).toBeGreaterThan(0);const jobs=await queue.boss.findJobs<{replyId:string;generation:number}>(queue.queueName+'-group-reply');expect(jobs).toHaveLength(1);expect(jobs[0]!.data).toMatchObject({replyId:p.replyId,generation:0});expect(JSON.stringify(jobs)).not.toContain('周五下午');let processed!:()=>void,failed!:(e:unknown)=>void;const done=new Promise<void>((resolve,reject)=>{processed=resolve;failed=reject;});await queue.workGroupReplies(async job=>{try{expect(await f.gateway.processGroupReply(job,job.replyId,job.generation)).toBe('APPLIED');processed();}catch(e){failed(e);throw e;}});await Promise.race([done,new Promise((_,reject)=>{const timer=setTimeout(()=>reject(Error('GROUP_QUEUE_NOT_PROCESSED')),10000);timer.unref();})]);expect((await replies(f))[0]).toMatchObject({state:'APPLIED',generation:'1'});expect(await queue.publish(smallDb,f.ctx)).toBeGreaterThan(0);const continuations=await queue.boss.findJobs<{runId:string;generation:number}>(queue.queueName);expect(continuations.filter(j=>j.data.runId===f.runId&&j.data.generation===1)).toHaveLength(1);await f.runtime.advance(f.ctx,f.runId,undefined,undefined,1);expect(await f.state()).toMatchObject({status:'SUCCEEDED',result:f.answer});}finally{await queue.stop();await smallDb.close();}
},60000);
it.each(['TENANT','USER','TASK','GROUP','CONNECTOR'] as const)('%s ALL stop blocks the new group authority reader before any CLI metadata read or model dispatch',async scope=>{
 const f=await fresh(),scopeId={TENANT:f.ctx.tenantId,USER:f.ctx.actorId,TASK:f.taskId,GROUP:f.conversationId,CONNECTOR:'DWS'}[scope];await root.query("INSERT INTO kill_switches(tenant_id,id,issuer_id,scope_kind,scope_id,mode,enabled,reason_hash) VALUES($1,$2,$3,$4,$5,'ALL',true,'synthetic-stop')",[f.ctx.tenantId,randomUUID(),f.ctx.actorId,scope,scopeId]);await f.runtime.advance(f.ctx,f.runId);expect(await f.state()).toMatchObject({status:'WAITING_AUTH',last_error:'GROUP_AUDIENCE_UNVERIFIED'});expect(await reads(f)).toBe(0);expect((await f.fixture.events()).filter(e=>e.phase==='GROUP_INFO')).toHaveLength(0);expect(f.requests).toHaveLength(0);expect((await db.scope(f.ctx,c=>c.query('SELECT id FROM run_group_audiences WHERE run_id=$1',[f.runId]))).rowCount).toBe(0);
},60000);
