it.each(['load-tool','load-call','load-ledger','rebuild-tool','rebuild-call','rebuild-ledger'] as const)('%s refuses historical private tool material before group model egress or checkpoint reconstruction',async mode=>{
 const f=await fresh(),original=(await root.query('SELECT audience FROM tasks WHERE id=$1',[f.taskId])).rows[0].audience;
 if(mode.endsWith('ledger')){await root.query('UPDATE tasks SET audience=$2 WHERE id=$1',[f.taskId,JSON.stringify({kind:'PRIVATE_USER',targetId:f.ctx.actorId,classificationCeiling:'RESTRICTED'})]);const privateLease=(await f.store.acquire(f.ctx,f.runId,'synthetic-prior-private-context'))!,privateGateway=syntheticTextGateway(f.store,'SYNTHETIC_PRIVATE_GROUP_LEAK');try{expect((await privateGateway.execute(f.ctx,privateLease,(await privateGateway.tools(f.ctx,privateLease))[0]!.function.name,{},new AbortController().signal)).status).toBe('OK');}finally{await f.store.release(f.ctx,privateLease);}await root.query('UPDATE tasks SET audience=$2 WHERE id=$1',[f.taskId,JSON.stringify(original)]);}
 const lease=(await f.store.acquire(f.ctx,f.runId,'group-context-guard'))!;try{expect(await f.gateway.prepareAudience(f.ctx,lease,new AbortController().signal)).toBe(true);if(mode.endsWith('tool'))await f.store.append(f.ctx,lease,{role:'tool',tool_call_id:'untrusted-history',content:'SYNTHETIC_PRIVATE_GROUP_LEAK'});if(mode.endsWith('call'))await f.store.append(f.ctx,lease,{role:'assistant',content:null,tool_calls:[{id:'untrusted-history',type:'function',function:{name:'untrusted-tool',arguments:'{}'}}]});const history=await f.store.history(f.ctx,lease);if(!mode.endsWith('ledger')){expect(await f.gateway.contextAllowed(f.ctx,lease,history)).toBe(false);expect(await f.store.guarded(f.ctx,lease,c=>f.gateway.modelDispatchReason(f.ctx,lease,history,c))).toBe('MODEL_CONTEXT_CHANGED_BEFORE_DISPATCH');}const result=mode.startsWith('load')?await f.gateway.loadContext(f.ctx,lease):await f.gateway.rebuildContext(f.ctx,lease,'AUTHORIZATION_CHANGED',history);expect(result).toEqual({messages:[],blocked:true});expect(await f.state()).toMatchObject({status:'PARTIAL',last_error:'GROUP_RESOURCE_SHARING_UNCERTIFIED',result:null});expect(f.requests).toHaveLength(0);expect((await db.scope(f.ctx,c=>c.query('SELECT id FROM context_checkpoints WHERE run_id=$1',[f.runId]))).rowCount).toBe(0);expect((await db.scope(f.ctx,c=>c.query('SELECT id FROM deliveries WHERE source_run_id=$1',[f.runId]))).rowCount).toBe(0);}finally{await f.store.release(f.ctx,lease);}
},60000);
