it('expired group journals rebuild the accepted question and authenticated answer with the original audience, goal and budget',async()=>{
 const f=await fresh(),p=await pending(f),original=(await root.query('SELECT budget,group_audience_id FROM runs WHERE id=$1',[f.runId])).rows[0];expect(await f.gateway.processGroupReply(f.ctx,p.replyId)).toBe('APPLIED');await root.query("UPDATE provider_journals SET expires_at=clock_timestamp()-interval '1 second' WHERE run_id=$1",[f.runId]);await f.runtime.advance(f.ctx,f.runId,undefined,undefined,1);expect(await f.state()).toMatchObject({status:'SUCCEEDED',result:f.answer});expect(f.requests).toHaveLength(4);const restored=f.requests[2]!.messages.find(m=>m.content?.startsWith('SAVED_AUTHENTICATED_CLARIFICATION_DATA'));expect(restored).toBeDefined();expect(restored!.content).toContain('邀请用于哪种活动');expect(restored!.content).toContain('第一个，周五下午三点');expect(restored!.content).toContain(p.reviewId);expect((await root.query('SELECT budget,group_audience_id FROM runs WHERE id=$1',[f.runId])).rows[0]).toEqual(original);expect((await replies(f))[0]).toMatchObject({state:'APPLIED',generation:'1'});
},60000);
it.each(['lease-ref','run-pointer'] as const)('a frozen group question with missing %s cannot be viewed or reach a physical sender',async kind=>{
 const f=await fresh();await question(f);const result=(await f.state()).result as string,delivery=(await db.scope(f.ctx,c=>c.query('SELECT * FROM deliveries WHERE source_run_id=$1',[f.runId]))).rows[0];if(kind==='run-pointer')await root.query('UPDATE runs SET group_audience_id=NULL WHERE id=$1',[f.runId]);else{const final=(await root.query('SELECT id,plan_ref FROM run_finalizations WHERE id=$1',[delivery.finalization_id])).rows[0],aad=`${f.ctx.tenantId}:${f.ctx.actorId}:final:${final.id}`,proof=JSON.parse(vault.open(final.plan_ref,aad));delete proof.lease.groupAudience;await root.query('UPDATE run_finalizations SET plan_ref=$2 WHERE id=$1',[final.id,JSON.stringify(vault.seal(JSON.stringify(proof),aad))]);}expect(await f.gateway.finalResultAllowed(f.ctx,f.runId,result)).toBe(false);let sends=0;expect(await sender(f,()=>sends++).process(f.ctx,delivery.id,new AbortController().signal)).toBe('SUPPRESSED');expect(sends).toBe(0);expect(f.requests).toHaveLength(2);
},60000);
